#!/bin/sh
# Generated by forge. PostToolUse(Edit|Write), asyncRewake: project typecheck.
# Errors in changed files: exit 2 with <= 20 lines on stderr; errors only in
# unchanged files are not Claude's and stay silent. Skips if a typecheck is already
# running (lock directory in .forge/state/, taken over when its pid is gone).
dir=$(cd "$(dirname "$0")" && pwd)
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
file=$(json_get file_path)
[ -n "$file" ] || exit 0
file=$(rel_path "$file") || exit 0
case $file in .forge/*|.claude/*|.git/*|node_modules/*|.venv/*) exit 0 ;; esac
IFS='
'

@@CHECKS@@

_tc_any=0
_tc_i=1
while [ "$_tc_i" -le "$FORGE_NCHECKS" ]; do
  forge_check_meta_"$_tc_i"
  if [ "$c_stage" = typecheck ] && forge_scope_"$_tc_i" "$file"; then _tc_any=1; fi
  _tc_i=$((_tc_i + 1))
done
[ "$_tc_any" = 1 ] || exit 0

mkdir -p .forge/state 2>/dev/null || exit 0
lock=.forge/state/typecheck.lock
if ! mkdir "$lock" 2>/dev/null; then
  pid=$(cat "$lock/pid" 2>/dev/null)
  if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then exit 0; fi
  rm -rf "$lock"
  mkdir "$lock" 2>/dev/null || exit 0
fi
printf '%s\n' "$$" > "$lock/pid"
FORGE_TMP=$(mktemp -d "${TMPDIR:-/tmp}/forge-tc.XXXXXX") || { rm -rf "$lock"; exit 0; }
trap 'rm -rf "$FORGE_TMP" "$lock"' EXIT HUP INT TERM

# the changed set, as check.sh --changed computes it
git status --porcelain --untracked-files=all 2>/dev/null \
  | sed -e 's/^...//' -e 's/^.* -> //' -e 's/^"\(.*\)"$/\1/' | sort -u > "$FORGE_TMP/changed"
if forge_typecheck "$file" > "$FORGE_TMP/report" 2>&1; then exit 0; fi
first_lines 20 < "$FORGE_TMP/report" >&2
exit 2
